```suggestion
 if (listTiles[row][col].Count == 0)
 return;
 int previousIndex = alignment == DockPaneAlignment.Bottom ? row - 1 : col - 1;
 if (previousIndex < 0)
 return;
 if (alignment == DockPaneAlignment.Bottom)
 {
 if (col >= listTiles[previousIndex].Count)
 return;
 if (listTiles[previousIndex][col].Count == 0)
 return;
 }
 else
 {
 if (listTiles[row][previousIndex].Count == 0)
 return;
 }
```

