// Deprecated: Use ReaderWithError() to handle errors.
func (r GraphQLRequest) Reader() io.Reader {
 reader, err := r.ReaderWithError()
 if err != nil {
 // For backward compatibility, panic on error.
 panic(err)
 }
 return reader
}

